using System.Collections.Generic;
namespace RTMaquetaXR { internal static partial class ModLocalization {
    // Reviewed 0.1.59 tutorial edition. Existing source keys intentionally
    // receive the current, shorter Spanish wording after historical catalogues.
    static partial void AddGuide59(Dictionary<string,string> d) {
        d["Star map · warp routes"] = "Mapa estelar";
        d["Galactic map · system planets"] = "Mapa galáctico";
        d["Select and frame"] = "Seleccionar y encuadrar";
        d["Right trigger: click / double-click"] = "Gatillo derecho: clic / doble clic";
        d["One click selects or orders; two clicks frame."] = "Un clic selecciona u ordena; dos clics encuadran.";
        d["Point with the right skull. Click a character or ship to select it, or valid ground to give the native order. Selection never moves the camera. Double-click the same character or ship within 0.35 s to frame it along its heading, relative to its height. A also clicks. Map double-clicks keep their native function."] = "Apunta con el cráneo derecho. Un clic selecciona al personaje o nave, o da la orden nativa sobre terreno válido. Seleccionar no mueve la cámara. Dos clics sobre el mismo personaje o nave en 0,35 s lo encuadran según su rumbo y altura. A también hace clic. En los mapas, el doble clic conserva su función original.";
        d["First-person view"] = "Vista en primera persona";
        d["Right trigger fully held: 2 s"] = "Gatillo derecho a fondo: 2 s";
        d["Hold on a character or ship. B / zoom out leaves."] = "Mantén sobre personaje o nave. B / alejar sale.";
        d["Point at the character or ship and hold the right trigger at least 95% down for 2 s, without a grip. Its model is hidden from the VR eyes; heading changes are smoothed. Your head stays free. Left stick turns horizontally. B or bringing both gripped hands together returns to the table. Menus and navigation maps do not enter first person."] = "Apunta al personaje o nave y mantén el gatillo derecho al menos al 95 % durante 2 s, sin grip. Su modelo se oculta en VR y los giros se suavizan. Tu cabeza sigue libre. El stick izquierdo gira horizontalmente. B o juntar las manos con ambos grips vuelve a la maqueta. No funciona en menús ni mapas de navegación.";
        d["Move in first person"] = "Mover en primera persona";
        d["Full right trigger: 3 s in ground combat; 2 s exploring"] = "Gatillo derecho a fondo: 3 s en combate; 2 s al explorar";
        d["Hold over a valid destination until the move is accepted."] = "Mantén sobre un destino válido hasta aceptar el movimiento.";
        d["Without a grip, hold the right trigger at least 95% down over a valid ground destination: 3 s in Ground combat or 2 s in On-foot exploration. After the game accepts the move, the selected actor enters head view. It uses the normal move and action points. It cannot bypass invalid paths, enemy turns, ability targeting or deployment. Optional; enabled by default."] = "Sin grip, mantén el gatillo derecho al menos al 95 % sobre un destino válido: 3 s en Combates terrestres o 2 s en Exploración a pie. Tras aceptar el juego el movimiento, entras en la vista del actor. Usa el movimiento y los puntos normales. No evita rutas inválidas, turnos enemigos, apuntado de habilidades ni despliegue. Opcional; activado por defecto.";
        d["Select a group"] = "Seleccionar un grupo";
        d["Right trigger: hold and drag"] = "Gatillo derecho: mantener y arrastrar";
        d["Release to select; camera stays."] = "Suelta para seleccionar; la cámara no se mueve.";
        d["Start on ground or a controllable character, drag the rectangle around the group and release the right trigger. This is a mouse-style group selection, not a camera command. It applies on foot, not to navigation maps or ships. To frame an actor, double-click it instead. B cancels a pending order."] = "Empieza en el suelo o sobre un personaje controlable, arrastra el rectángulo alrededor del grupo y suelta el gatillo derecho. Selecciona como el ratón, sin ordenar un encuadre. Se aplica a pie, no a mapas de navegación ni naves. Para encuadrar un actor, haz doble clic sobre él. B cancela una orden pendiente.";
        d["Move the group"] = "Mover el grupo";
        d["Right stick + right controller aim"] = "Stick derecho y apuntado del Touch derecho";
        d["The right aim defines all four movement directions."] = "El apuntado derecho orienta las cuatro direcciones.";
        d["In On-foot exploration, the right aim at departure defines forward, backward and sideways movement. Move the right stick and turn your wrist to steer; centre the stick to set a new reference. Camera follow does not redirect the movement. Passing the ray over HUD does not stop it; clicking or opening a menu does. Combat uses native pointer orders."] = "En Exploración a pie, el apuntado derecho al empezar orienta avance, retroceso y desplazamiento lateral. Mueve el stick derecho y gira la muñeca para dirigir; centra el stick para fijar otra referencia. El seguimiento de cámara no redirige el movimiento. Pasar sobre el HUD no lo detiene; pulsar o abrir un menú sí. En combate se ordena con el puntero.";
        d["Move the table"] = "Mover la maqueta";
        d["Either grip: hold and move"] = "Un grip: mantener y mover";
        d["Move your hand to reposition the tabletop."] = "Mueve la mano para desplazar la maqueta.";
        d["Hold either grip, move that hand and release when the table is where you want it. The gesture works in On-foot exploration, both combat modes and 3D dialogue scenes. Your physical head stays free. Grips do not drag Management screens or navigation-map panels; those have independent placement settings."] = "Mantén un grip, mueve esa mano y suelta cuando la maqueta esté donde quieres. Funciona en Exploración a pie, ambos combates y diálogos en 3D. Tu cabeza se mueve libremente. Los grips no arrastran las Pantallas de gestión ni los paneles de mapas; estos tienen ajustes de posición independientes.";
        d["Rotate and zoom"] = "Girar y hacer zoom";
        d["Both grips: hold"] = "Ambos grips: mantener";
        d["Turn to rotate. Apart: closer. Together: farther."] = "Gira para rotar. Separa: acerca. Junta: aleja.";
        d["Hold both grips and rotate the line between the skulls, or change their separation. Gesture rotation is 15% gentler than before; adjust Gesture rotation sensitivity in Advanced settings > Tabletop. That control does not change stick turning or zoom. Bringing the hands together also leaves first person. Release the grips before using the left stick."] = "Mantén ambos grips y gira la línea entre los cráneos o cambia su separación. El giro gestual es un 15 % más suave; ajústalo en Configuración avanzada > Maqueta > Sensibilidad del giro gestual. Ese ajuste no modifica el giro del stick ni el zoom. Juntar las manos también sale de primera persona. Suelta los grips antes de usar el stick izquierdo.";
        d["Rotate / tilt the table"] = "Girar / inclinar la maqueta";
        d["Left stick"] = "Stick izquierdo";
        d["Left/right: rotate. Up/down: tilt."] = "Izquierda/derecha: gira. Arriba/abajo: inclina.";
        d["The LEFT stick rotates or tilts the table. In first person, left/right turns your view in both combat modes too. The Space combat board stays level sideways. An open wheel uses its stick to choose sectors instead. Centre the stick after a grip, wheel or menu before controlling the table again."] = "El stick IZQUIERDO gira o inclina la maqueta. En primera persona, izquierda/derecha gira la vista también en ambos combates. El tablero de Combate espacial se mantiene nivelado lateralmente. Una rueda abierta usa su stick para elegir sectores. Centra el stick tras un grip, rueda o menú antes de volver a controlar la maqueta.";
        d["Right wheel"] = "Rueda derecha";
        d["Right grip + trigger: 0.15 s"] = "Grip y gatillo derechos: 0,15 s";
        d["Native menus wherever the right options panel exists."] = "Menús nativos donde exista el panel de opciones derecho.";
        d["Hold right grip and trigger. Keep the RIGHT stick on a valid option for 1 s, or point with the LEFT skull and click its trigger. The wheel includes the original menus in navigation maps and Space combat. Grey options cannot run. Releasing the opening controls or B closes it. All four grips/triggers together reserve VR settings."] = "Mantén grip y gatillo derechos. Deja el stick DERECHO sobre una opción válida 1 s, o apunta con el cráneo IZQUIERDO y pulsa su gatillo. Incluye los menús originales de los mapas y del Combate espacial. Las opciones grises no se ejecutan. Soltar la combinación o B cierra. Los cuatro grips/gatillos juntos reservan los ajustes VR.";
        d["Left wheel · actions"] = "Rueda izquierda · acciones";
        d["Left grip + trigger: 0.15 s"] = "Grip y gatillo izquierdos: 0,15 s";
        d["Weapons inside; other abilities outside. No pages."] = "Armas dentro; otras habilidades fuera. Sin páginas.";
        d["Hold the left grip and trigger. Move the LEFT stick inward or farther out to select the inner or outer ring; a tolerance band stabilises the change. Or point with the RIGHT skull. Pointing previews native ability information; A or the RIGHT trigger executes an available ability. Grey actions cannot run. Release the opening controls to close."] = "Mantén grip y gatillo izquierdos. Mueve el stick IZQUIERDO hacia dentro o más afuera para elegir aro; una banda de tolerancia estabiliza el cambio. También puedes apuntar con el cráneo DERECHO. Señalar muestra la ficha nativa; A o gatillo DERECHO ejecuta una habilidad disponible. Las acciones grises no se usan. Suelta la combinación para cerrar.";
        d["Weapons and their actions"] = "Armas y sus acciones";
        d["Left wheel: inner / outer ring"] = "Rueda izquierda: aro interior / exterior";
        d["Active weapon in the centre; dynamic native choices."] = "Arma activa en el centro; opciones nativas dinámicas.";
        d["The centre identifies the active weapon or equipment set with its original art. Changing weapon is distinct from attacks, ammunition/effects and reload. The wheel follows the selected actor, current equipment and available abilities. After a weapon change the wheel refreshes: centre the stick and release confirmation before choosing the next action."] = "El centro identifica el arma o conjunto activo con su arte original. Cambiar de arma se distingue de ataques, munición/efectos y recarga. La rueda sigue al actor, su equipo y habilidades actuales. Al cambiar de arma se actualiza: centra el stick y suelta la confirmación antes de elegir otra acción.";
        d["Left wheel · participants"] = "Rueda izquierda · participantes";
        d["Left stick click: switch mode"] = "Clic del stick izquierdo: cambiar modo";
        d["Actions / Characters; Actions / Ships in space."] = "Acciones / Personajes; Acciones / Naves en el espacio.";
        d["Click the LEFT stick to alternate modes. In exploration, actions require exactly one selected character; party selection uses a 1 s stick hold or RIGHT-trigger click and never moves the camera. Ground deployment opens Characters first and a friendly portrait also selects that unit for placement. Active battles open Actions first. Extra participants use another ring."] = "Pulsa el stick IZQUIERDO para alternar modos. Al explorar, Acciones necesita un único personaje seleccionado; el grupo se elige con 1 s de stick o clic del gatillo DERECHO, sin mover la cámara. El despliegue terrestre abre Personajes y un retrato aliado también lo selecciona para colocarlo. La batalla abre Acciones. Si hay muchos actores, se añade otro aro.";
        d["Inspect a combatant"] = "Consultar un combatiente";
        d["Left stick / pointed right-trigger click"] = "Stick izquierdo / apuntar y pulsar gatillo derecho";
        d["Native information for allies, enemies and ships."] = "Información original de aliados, enemigos y naves.";
        d["In the participant wheel, move the LEFT stick onto a portrait to open its card immediately, or point with the RIGHT skull and click its trigger. Centre the stick to keep the card; another portrait replaces it. Consultation during a battle never selects or moves the camera. Release the wheel, press B or click LEFT stick to close the card."] = "En la rueda de participantes, lleva el stick IZQUIERDO a un retrato para abrir su ficha al instante, o apunta con el cráneo DERECHO y pulsa su gatillo. Centrar conserva la ficha; otro retrato la sustituye. Consultar durante una batalla no selecciona ni mueve la cámara. Suelta la rueda, pulsa B o clic del stick IZQUIERDO para cerrar la ficha.";
        d["Read original information"] = "Leer información original";
        d["Point to preview; right stick to scroll"] = "Señalar para consultar; stick derecho para desplazar";
        d["Stable native cards, centred slightly to the right."] = "Fichas originales estables, centradas algo a la derecha.";
        d["Wheel cards keep their own scale and fixed place in the view, independently of the wheel and HUD size. They are 25% smaller than the previous release. Centre the RIGHT stick after a new card opens, then move it up/down to scroll long information. An ability preview disappears when no longer pointed at; participant cards remain until changed or closed."] = "Las fichas conservan escala y lugar fijos en la vista, independientes de la rueda y del tamaño del HUD. Son un 25 % menores que en la entrega anterior. Centra el stick DERECHO tras abrir otra ficha y muévelo arriba/abajo para leer contenido largo. La ficha de habilidad se oculta al dejar de señalar; la de participante permanece hasta cambiarla o cerrarla.";
        d["End the turn"] = "Terminar el turno";
        d["Choose End turn, then hold A / opposite trigger: 2 s"] = "Elige Terminar turno; mantén A / gatillo contrario: 2 s";
        d["Keep the confirmation held until its progress completes."] = "Mantén la confirmación hasta completar el progreso.";
        d["In either combat, choose the skull with the LEFT stick or opposite Touch. Hold A or the opposite trigger for 2 s. After starting confirmation, the stick may return to centre. Choosing another sector, releasing confirmation or closing the wheel cancels the progress. Pointing alone, a short click or releasing the opening grips never ends the turn."] = "En ambos combates, elige la calavera con el stick IZQUIERDO o Touch contrario. Mantén A o el gatillo contrario 2 s. Tras empezar la confirmación, puedes centrar el stick. Elegir otro sector, soltar la confirmación o cerrar la rueda cancela el progreso. Sólo señalar, un clic corto o soltar los grips de apertura nunca termina el turno.";
        d["Combat status on the wheel"] = "Estado del combate en la rueda";
        d["Left wheel: native live indicators"] = "Rueda izquierda: indicadores originales vivos";
        d["Veil, momentum and the selected ally; ship integrity in space."] = "Velo, ímpetu y aliado seleccionado; integridad en el espacio.";
        d["Ground combat keeps the original veil and momentum indicators on the left wheel, plus health, action/movement points and effects for the selected ally. Inspecting an enemy does not replace that ally. Space combat shows our ship integrity. Participant order numbers and the player-turn highlight follow the native battle; unavailable actions remain grey."] = "En Combates terrestres, la rueda izquierda muestra velo e ímpetu originales, además de vida, puntos de acción/movimiento y efectos del aliado seleccionado. Consultar un enemigo no sustituye a ese aliado. En Combate espacial muestra la integridad de nuestra nave. El orden y el destacado del turno siguen al juego; las acciones no disponibles quedan grises.";
        d["Map / reveal objects"] = "Mapa / resaltar objetos";
        d["Map: LEFT click · highlights: hold RIGHT click"] = "Mapa: clic IZQUIERDO · objetos: mantener clic DERECHO";
        d["Exploration shortcuts; short RIGHT click toggles help."] = "Atajos de exploración; clic DERECHO corto alterna ayudas.";
        d["Outside combat, click the LEFT stick to open the local map; the right wheel opens the same view. RIGHT stick pans; LEFT up/down zooms and left/right rotates. B or LEFT click closes it. In exploration, hold the RIGHT stick click for more than half a second to highlight objects while held. A short click instead toggles the controls reminder."] = "Fuera de combate, clic del stick IZQUIERDO abre el mapa local; la rueda derecha abre la misma vista. Stick DERECHO desplaza; IZQUIERDO hace zoom arriba/abajo y gira izquierda/derecha. B o clic IZQUIERDO cierra. Al explorar, mantén clic del stick DERECHO más de medio segundo para resaltar objetos. Un clic corto alterna las ayudas.";
        d["Cancel / back"] = "Cancelar / volver";
        d["Left trigger / B"] = "Gatillo izquierdo / B";
        d["B cancels the current order, wheel or window."] = "B cancela la orden, rueda o ventana actual.";
        d["B cancels the current interaction, closes the active wheel/settings/native window or cancels an order. In gameplay it also leaves first person. The left menu button is Back/Cancel. The left trigger performs the native secondary click; when the right wheel is open it confirms the option pointed at by the left skull instead."] = "B cancela la interacción actual, cierra rueda/ajustes/ventana nativa o cancela una orden. En partida también sale de primera persona. El botón de menú izquierdo hace Volver/Cancelar. El gatillo izquierdo hace clic secundario nativo; con la rueda derecha abierta confirma la opción señalada por el cráneo izquierdo.";
        d["Pause"] = "Pausa";
        d["X button"] = "Botón X";
        d["Pause or resume the game."] = "Pausar o reanudar el juego.";
        d["Press X when gameplay input is available to invoke the original pause action. This does not skip a turn or interrupt a native modal window. B cancels a pending action; use the right-trigger pointer for native menu buttons."] = "Pulsa X cuando el juego admite controles para activar su pausa original. No salta un turno ni interrumpe una ventana modal nativa. B cancela una acción pendiente; usa el puntero del gatillo derecho para los botones del juego.";
        d["VR settings"] = "Ajustes VR";
        d["Both triggers + grips: 2 s"] = "Ambos gatillos y grips: 2 s";
        d["Open or close settings. Takes priority over wheels."] = "Abre o cierra ajustes. Tiene prioridad sobre las ruedas.";
        d["Hold both triggers and both grips together for 2 s to open or close settings. Release all four before repeating. The chord cancels any open wheel without running its action. F1 also opens or closes the panel and takes priority over any game binding. Every mod-owned screen can switch between English and Spanish."] = "Mantén ambos gatillos y ambos grips juntos durante 2 s para abrir o cerrar ajustes. Suelta los cuatro antes de repetir. La combinación cancela las ruedas abiertas sin ejecutar su acción. F1 también abre o cierra y tiene prioridad sobre cualquier asignación del juego. Las pantallas propias permiten castellano o inglés.";
        d["Use VR settings"] = "Usar los ajustes VR";
        d["Point + A / right trigger"] = "Apunta y pulsa A / gatillo derecho";
        d["A or trigger activates the pointed control. B returns."] = "A o gatillo activa el control señalado. B vuelve.";
        d["Point at a row or button and release A or the RIGHT trigger over it to activate. Release both before confirming again. The RIGHT stick navigates and changes values; away from the panel, A/trigger uses the focused option. B goes back. F1 toggles settings, F2/F3 change a value and F4 activates the focused action."] = "Señala una fila o botón y suelta A o el gatillo DERECHO sobre él para activar. Suelta ambos antes de confirmar otra vez. El stick DERECHO navega y cambia valores; fuera del panel, A/gatillo usa la opción enfocada. B vuelve. F1 alterna ajustes, F2/F3 cambian un valor y F4 activa la acción enfocada.";
        d["Keyboard settings shortcut"] = "Atajo de ajustes con teclado";
        d["Open or close VR settings and help."] = "Abrir o cerrar ajustes VR y ayudas.";
        d["F1 opens/closes the mod settings and takes priority over the game binding. Holding it only acts once. Return to this tutorial through Advanced settings > Help · Touch controls. The welcome asks once, after the first playable load of each launch; YES opens the tutorial directly and NO continues the game."] = "F1 abre/cierra los ajustes y tiene prioridad sobre la asignación del juego. Mantenerlo sólo actúa una vez. Vuelve a este tutorial en Configuración avanzada > Ayuda · Controles Touch. La bienvenida pregunta una vez tras la primera carga jugable de cada arranque; SÍ abre el tutorial y NO continúa.";
        d["Control reminders"] = "Recordatorios de controles";
        d["Short RIGHT stick click"] = "Clic corto del stick DERECHO";
        d["Hidden at launch. Available in exploration and both combats."] = "Ocultos al arrancar. Disponibles al explorar y combatir.";
        d["A short RIGHT-stick click shows/hides contextual controls in On-foot exploration, Ground combat and Space combat. They stay hidden on the main menu, maps and dialogue. Size and placement are adjustable in Advanced settings. Holding that click to highlight objects does not toggle help. The separate gesture indicator is optional and off by default."] = "Un clic corto del stick DERECHO muestra/oculta controles en Exploración a pie, Combates terrestres y Combate espacial. No aparecen en menú principal, mapas ni diálogos. Su tamaño y posición se ajustan en Configuración avanzada. Mantener clic para resaltar objetos no alterna la ayuda. El indicador gestual es opcional y está apagado por defecto.";
        d["Star and galactic maps"] = "Mapa estelar y Mapa galáctico";
        d["RIGHT stick: pan · LEFT up/down: zoom"] = "Stick DERECHO: desplaza · IZQUIERDO: zoom arriba/abajo";
        d["Star map: warp routes. Galactic map: system planets."] = "Estelar: rutas de disformidad. Galáctico: planetas del sistema.";
        d["Centre both sticks after opening the map. RIGHT stick pans; LEFT up/down zooms. Point with the right skull and click or press A for native objects, routes and travel confirmations. B goes back. The right wheel supplies the original options. These maps have no group movement, selection rectangle or first-person view."] = "Centra ambos sticks al abrir el mapa. El DERECHO desplaza; el IZQUIERDO arriba/abajo hace zoom. Apunta con el cráneo derecho y pulsa gatillo o A para objetos, rutas y confirmaciones originales. B vuelve. La rueda derecha ofrece las opciones del juego. No hay movimiento de grupo, selección rectangular ni primera persona.";
        d["Adjust each map panel"] = "Ajustar cada panel de mapa";
        d["Advanced settings > Space"] = "Configuración avanzada > Espacio";
        d["Each navigation map saves its own placement and content zoom."] = "Cada mapa guarda posición y zoom de contenido propios.";
        d["Star map (warp routes) and Galactic map (planets) have independent width, distance, proportions, position, content zoom and saved layouts in Advanced settings > Space. Changing one map does not resize the other. Panel size changes how large the whole window looks; content zoom changes the map inside it."] = "Mapa estelar (rutas de disformidad) y Mapa galáctico (planetas) tienen anchura, distancia, proporciones, posición, zoom de contenido y presets independientes en Configuración avanzada > Espacio. Ajustar uno no cambia el otro. Tamaño del panel cambia la ventana completa; zoom de contenido cambia el mapa de dentro.";
        d["Space combat controls"] = "Controles del Combate espacial";
        d["Table gestures + native tactical pointer"] = "Gestos de maqueta y puntero táctico nativo";
        d["Click orders. Double-click frames. Deep hold: first person."] = "Clic ordena. Doble clic encuadra. Mantener a fondo: primera persona.";
        d["Battle entry frames our ship; the board stays level sideways. Click ships or ground to issue native tactical orders without moving the camera. Double-click a ship to frame its heading; hold the full RIGHT trigger 2 s over it for its view. LEFT wheel alternates actions/ships, RIGHT wheel opens menus. Native ranges, resources and cooldowns still apply."] = "Al entrar se encuadra nuestra nave y el tablero se nivela lateralmente. Clic en naves o terreno da órdenes tácticas sin mover la cámara. Doble clic encuadra según el rumbo; mantén gatillo DERECHO a fondo 2 s sobre la nave para entrar en su vista. Rueda IZQUIERDA alterna acciones/naves; DERECHA abre menús. Se respetan alcance, recursos y recargas.";
        d["Native windows and dialogue"] = "Ventanas nativas y diálogos";
        d["Right aim + trigger / A · RIGHT stick: scroll"] = "Apuntado derecho + gatillo / A · stick DERECHO: desplaza";
        d["Use the original choices, equipment and story-book pages."] = "Usa las opciones, equipo y páginas narrativas originales.";
        d["Point with the right skull and click the RIGHT trigger or A. The RIGHT stick scrolls long native content; centre it after opening a new window. B returns or cancels when the game permits. Dialogue choices, tutorial notices and story-book decisions keep their native rules. Settings do not choose a dialogue answer for you."] = "Apunta con el cráneo derecho y pulsa gatillo DERECHO o A. El stick DERECHO desplaza contenido largo; céntralo tras abrir otra ventana. B vuelve o cancela cuando el juego permite. Diálogos, avisos tutoriales y decisiones del libro conservan sus reglas. Los ajustes no eligen una respuesta por ti.";
        d["Camera during dialogue"] = "Cámara durante diálogos";
        d["Grips + LEFT stick in 3D scenes"] = "Grips y stick IZQUIERDO en escenas 3D";
        d["Automatic close framing; you can adjust the scene view."] = "Encuadre cercano automático; puedes ajustar la vista.";
        d["3D dialogue scenes use their own close framing. Reposition with one grip, rotate/zoom with two grips or rotate/tilt with the LEFT stick. Your head remains free. Native text choices still use the right pointer. Returning from ordinary windows restores the earlier table position; it does not frame the group again."] = "Los diálogos 3D usan su encuadre cercano. Desplaza con un grip, gira/haz zoom con dos grips o gira/inclina con el stick IZQUIERDO. La cabeza sigue libre. El texto nativo se elige con el puntero derecho. Volver de ventanas normales recupera la posición previa; no vuelve a encuadrar el grupo.";
        d["Compare weapons"] = "Comparar armas";
        d["Point at a weapon + Y"] = "Apunta a un arma + Y";
        d["Open the original weapon comparisons together."] = "Abre juntas las comparaciones originales de armas.";
        d["In Management screens, point the right skull at an inventory/equipment weapon and press Y. The game shows that weapon alongside equipped weapons eligible for comparison, with its own statistics, bonuses and art. RIGHT stick scrolls; B closes. This never equips, sells or discards an item."] = "En Pantallas de gestión, apunta con el cráneo derecho a un arma del inventario/equipo y pulsa Y. El juego la compara con las armas equipadas compatibles, usando estadísticas, bonificaciones y arte originales. Stick DERECHO desplaza; B cierra. Esta consulta no equipa, vende ni descarta objetos.";
        d["Fit native windows"] = "Ajustar las ventanas nativas";
        d["Advanced settings > Interface / Space"] = "Configuración avanzada > Interfaz / Espacio";
        d["Dialogue, management and navigation maps have separate layouts."] = "Diálogos, gestión y mapas tienen ajustes separados.";
        d["Adjust size, distance, aspect and position for the relevant screen, then save its HUD preset. Management windows and both navigation maps have their own settings. Wheels keep an independent physical size; information cards keep a fixed view position. Updating the mod preserves your saved custom layout."] = "Ajusta tamaño, distancia, proporción y posición de la pantalla correspondiente y guarda su preset de HUD. Pantallas de gestión y ambos mapas tienen ajustes propios. Las ruedas mantienen tamaño físico independiente; las fichas, posición fija en la vista. Actualizar el mod conserva tu colocación personalizada.";
        d["Draw distance"] = "Distancia de dibujado";
        d["Left thumbrest touch + right stick up/down"] = "Apoyo capacitivo izquierdo + stick derecho arriba/abajo";
        d["Surface only. Optional; off by default."] = "Sólo a pie. Opcional; apagado por defecto.";
        d["Enable Draw distance shortcut in Tabletop settings to use it during On-foot exploration and Ground combat. Rest your left thumb on the capacitive thumbrest, then move the RIGHT stick up to draw farther or down to draw less. No click is needed. Centre the stick after releasing the thumbrest. It is inactive in navigation maps and Space combat."] = "Activa Atajo de distancia de dibujado en Maqueta para usarlo en Exploración a pie y Combates terrestres. Apoya el pulgar izquierdo en la zona capacitiva y mueve el stick DERECHO arriba para dibujar más lejos o abajo para reducir distancia. No pulses. Centra el stick al retirar el pulgar. No actúa en mapas ni Combate espacial.";
        d["Image and saved profiles"] = "Imagen y perfiles guardados";
        d["Main settings: image / profiles / SAVE"] = "Ajustes principales: imagen / perfiles / GUARDAR";
        d["Common controls first; full settings under Advanced."] = "Controles comunes primero; ajustes completos en Avanzada.";
        d["Choose rendering, output resolution, DLSS scale and engine effects on the main page. Custom starts with the reference configuration; SAVE stores your complete current setup and confirms it. Reset asks first and discards personal changes. DLSS/DLAA failure displays the current image without AA; TAA remains a separate manual choice."] = "Elige renderizado, resolución de salida, escala DLSS y efectos en la página principal. Personalizado comienza con nuestra referencia; GUARDAR conserva la configuración completa y lo confirma. Restablecer pide confirmación y descarta cambios personales. Si falla DLSS/DLAA, muestra imagen sin AA; TAA sigue siendo una elección manual aparte.";
        d["Optional engine controls"] = "Controles opcionales del motor";
        d["Advanced settings: restart where indicated"] = "Configuración avanzada: reinicia cuando se indique";
        d["Experimental choices are optional, with no promised FPS gain."] = "Opciones experimentales; no se promete una ganancia de FPS.";
        d["Selective engine cadence is off by default. Its 72/36, 90/45 and 120/60 pairs require restart and do not change Virtual Desktop refresh. The engine-block switches also apply after restart. They do not halve every game system. Keep a configuration you can compare; your head, Touch and stereo views retain their own update paths."] = "La cadencia selectiva está apagada por defecto. Sus pares 72/36, 90/45 y 120/60 exigen reiniciar y no cambian el refresco de Virtual Desktop. Los interruptores de bloques del motor también se aplican al reiniciar. No dividen todo el juego a la mitad. Cabeza, Touch y vistas estéreo conservan sus actualizaciones propias.";
        d["Diagnostics and combat effects"] = "Trazas y efectos de combate";
        d["Main settings / Advanced settings"] = "Ajustes principales / Configuración avanzada";
        d["Optional logging and temporary combat effects."] = "Trazas opcionales y efectos temporales de combate.";
        d["The master diagnostics switch stops our managed/native traces and diagnostic collection; it does not silence the game or other mods. Automatic minimum combat effects is off by default. When enabled, ground deployment/combat temporarily uses Minimum and restores your chosen base level afterwards. It never overwrites that saved preference."] = "El interruptor general de trazas detiene nuestros registros y recogida de diagnóstico, también nativos; no silencia al juego ni otros mods. Efectos mínimos en combate está apagado por defecto. Al activarlo, despliegue/combate terrestre usa Mínimo temporalmente y después recupera tu nivel base, sin sobrescribir la preferencia guardada.";
        d["Gesture rotation sensitivity"] = "Sensibilidad del giro gestual";
        d["Adjust only rotation with both grips. At 100%, gesture turning is 15% gentler than 0.1.58. Stick turning, tilt, zoom and movement keep their existing response."] = "Ajusta sólo el giro con ambos grips. Al 100 %, el giro gestual es un 15 % más suave que en 0.1.58. El giro del stick, la inclinación, el zoom y el movimiento conservan su respuesta.";
    }
} }
